.gw-progress { position: relative; box-sizing: border-box; display: flex; flex-direction: column; width: 100%; min-width: 0; color: var(--dsw-alias-label-primary); font-family: var(--dsw-font-family-sans, inherit); font-size: 13px; }
.gw-progress-bar { display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 12px 4px 9px; border-bottom: 1px solid var(--dsw-alias-border-l2, currentColor); }
.gw-progress-run { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 13px; font-weight: 600; color: var(--dsw-alias-label-secondary, inherit); }
.gw-progress-chip { display: inline-flex; align-items: center; gap: 6px; flex: none; height: 24px; padding: 0 10px; border-radius: 999px; border: 1px solid var(--dsw-alias-border-l2, currentColor); background: color-mix(in srgb, var(--dsw-alias-state-idle-primary) 12%, transparent); color: var(--dsw-alias-label-secondary, inherit); font-size: 12px; font-weight: 600; white-space: nowrap; }
.gw-progress-chip-dot { display: inline-block; width: 6px; height: 6px; border-radius: 50%; background: currentColor; }
.gw-progress-chip[data-state="waiting"] { border-color: var(--dsw-alias-state-business-primary); background: var(--dsw-alias-state-business-primary); color: var(--dsw-alias-label-inverse, inherit); }
.gw-progress-chip[data-state="running"] { border-color: color-mix(in srgb, var(--dsw-alias-state-business-primary) 45%, transparent); background: color-mix(in srgb, var(--dsw-alias-state-business-primary) 10%, transparent); color: var(--dsw-alias-state-business-primary); }
.gw-progress-chip[data-state="running"] .gw-progress-chip-dot { animation: gw-progress-pulse 1.7s ease-in-out infinite; }
.gw-progress-chip[data-state="done"] { border-color: color-mix(in srgb, var(--dsw-alias-state-success-primary) 45%, transparent); background: color-mix(in srgb, var(--dsw-alias-state-success-primary) 10%, transparent); color: var(--dsw-alias-state-success-primary); }
.gw-progress-chip[data-state="failed"], .gw-progress-chip[data-state="cancelled"] { border-color: color-mix(in srgb, var(--dsw-alias-state-warn-primary) 45%, transparent); background: color-mix(in srgb, var(--dsw-alias-state-warn-primary) 10%, transparent); color: var(--dsw-alias-state-warn-primary); }
.gw-progress-flow { position: relative; box-sizing: border-box; display: block; width: 100%; min-width: 0; margin: 14px 0 0; padding: 0 4px; }
.gw-progress-wires { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; pointer-events: none; }
.gw-progress-wires > path { fill: none; stroke: var(--dsw-alias-border-l2, currentColor); stroke-width: 1.5; }
.gw-progress-cols { position: relative; z-index: 1; display: flex; flex-wrap: wrap; align-items: flex-start; gap: 12px; margin: 0; padding: 0; list-style: none; min-width: 0; }
.gw-progress-col { position: relative; box-sizing: border-box; display: flex; flex-direction: column; gap: 6px; flex: 1 1 0; min-width: 0; max-width: 100%; margin: 0; padding: 0; list-style: none; }
.gw-progress-node { position: relative; box-sizing: border-box; display: flex; align-items: center; gap: 6px; height: 32px; min-width: 0; max-width: 100%; padding: 0 10px; border: 1px solid var(--dsw-alias-border-l2, currentColor); border-radius: 10px; background-color: transparent; }
.gw-progress-node[data-kind="start"], .gw-progress-node[data-kind="end"] { border-radius: 999px; }
.gw-progress-node-dot { display: inline-block; flex: none; width: 7px; height: 7px; border-radius: 50%; background: var(--dsw-alias-state-idle-primary); }
.gw-progress-node-word { min-width: 0; flex: 1 1 auto; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 13px; font-weight: 600; }
.gw-progress-node-ord { flex: none; font-size: 11px; color: var(--dsw-alias-label-secondary, inherit); white-space: nowrap; font-variant-numeric: tabular-nums; }
.gw-progress-node[data-state="done"] { border-color: color-mix(in srgb, var(--dsw-alias-state-success-primary) 45%, transparent); background-color: transparent; background-image: linear-gradient(180deg, color-mix(in srgb, var(--dsw-alias-state-success-primary) 12%, transparent), color-mix(in srgb, var(--dsw-alias-state-success-primary) 5%, transparent)); }
.gw-progress-node[data-state="done"] .gw-progress-node-dot { background: var(--dsw-alias-state-success-primary); }
.gw-progress-node[data-state="done"] .gw-progress-node-word { color: var(--dsw-alias-state-success-primary); }
.gw-progress-node[data-state="doing"] { border-color: var(--dsw-alias-state-business-primary); background-color: transparent; background-image: linear-gradient(180deg, color-mix(in srgb, var(--dsw-alias-state-business-primary) 12%, transparent), color-mix(in srgb, var(--dsw-alias-state-business-primary) 5%, transparent)); box-shadow: 0 0 0 3px color-mix(in srgb, var(--dsw-alias-state-business-primary) 18%, transparent); }
.gw-progress-node[data-state="doing"] .gw-progress-node-dot { background: var(--dsw-alias-state-business-primary); animation: gw-progress-breathe 1.7s ease-in-out infinite; }
.gw-progress-node[data-state="doing"] .gw-progress-node-word { color: var(--dsw-alias-state-business-primary); }
.gw-progress-node[data-state="pending"] { border-style: dashed; background-color: transparent; background-image: none; }
.gw-progress-node[data-state="pending"] .gw-progress-node-dot { background: transparent; box-shadow: inset 0 0 0 1px var(--dsw-alias-state-idle-primary); }
.gw-progress-node[data-state="pending"] .gw-progress-node-word { color: var(--dsw-alias-label-secondary, inherit); }
.gw-progress-node[data-state="failed"], .gw-progress-node[data-state="blocked"], .gw-progress-node[data-state="cancelled"] { border-color: color-mix(in srgb, var(--dsw-alias-state-warn-primary) 50%, transparent); background-color: transparent; background-image: linear-gradient(180deg, color-mix(in srgb, var(--dsw-alias-state-warn-primary) 12%, transparent), color-mix(in srgb, var(--dsw-alias-state-warn-primary) 5%, transparent)); }
.gw-progress-node[data-state="failed"] .gw-progress-node-dot { background: var(--dsw-alias-state-warn-primary); }
.gw-progress-node[data-state="failed"] .gw-progress-node-word { color: var(--dsw-alias-state-warn-primary); }
.gw-progress-node[data-state="blocked"] .gw-progress-node-dot { background: var(--dsw-alias-state-warn-primary); }
.gw-progress-node[data-state="blocked"] .gw-progress-node-word { color: var(--dsw-alias-state-warn-primary); }
.gw-progress-node[data-state="cancelled"] .gw-progress-node-dot { background: var(--dsw-alias-state-warn-primary); }
.gw-progress-node[data-state="cancelled"] .gw-progress-node-word { color: var(--dsw-alias-state-warn-primary); }
.gw-progress-node-toggle { display: inline-flex; align-items: center; justify-content: center; flex: none; width: 18px; height: 18px; padding: 0; border: 0; border-radius: 999px; background: transparent; color: var(--dsw-alias-label-secondary, inherit); font: inherit; cursor: pointer; }
.gw-progress-node-toggle::after { content: ""; width: 5px; height: 5px; border-right: 1.5px solid currentColor; border-bottom: 1.5px solid currentColor; transform: rotate(45deg); }
.gw-progress-node-toggle[aria-expanded="true"]::after { transform: rotate(-135deg); }
.gw-progress-node-toggle:hover { color: var(--dsw-alias-state-business-primary); }
.gw-progress-node-toggle:focus-visible { outline: 2px solid var(--dsw-alias-state-business-primary); outline-offset: 2px; }
.gw-progress-node-calls, .gw-progress-sub-calls { position: absolute; z-index: 3; top: calc(100% + 6px); left: 0; right: 0; box-sizing: border-box; display: flex; flex-direction: column; min-width: 0; max-height: 240px; overflow-y: auto; margin: 0; padding: 6px; list-style: none; border: 1px solid var(--dsw-alias-border-l2, currentColor); border-radius: 10px; background: var(--dsw-alias-bg-elevated, var(--dsw-alias-bg-l1, transparent)); box-shadow: 0 6px 16px color-mix(in srgb, var(--dsw-alias-label-primary) 12%, transparent); }
.gw-progress-subs { display: grid; grid-template-rows: repeat(var(--gw-lanes, 1), 26px); gap: 6px; margin: 0; padding: 0; list-style: none; min-width: 0; }
.gw-progress-sub { position: relative; box-sizing: border-box; display: flex; align-items: center; gap: 4px; height: 26px; min-width: 0; max-width: 100%; padding: 3px 8px; border: 1px solid var(--dsw-alias-border-l2, currentColor); border-radius: 10px; font-size: 12px; background-color: transparent; }
.gw-progress-sub-dot { display: inline-block; flex: none; width: 6px; height: 6px; border-radius: 50%; background: var(--dsw-alias-state-idle-primary); }
.gw-progress-sub-word { min-width: 0; flex: 1 1 auto; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.gw-progress-sub[data-state="done"] { border-color: color-mix(in srgb, var(--dsw-alias-state-success-primary) 45%, transparent); background-color: transparent; background-image: linear-gradient(180deg, color-mix(in srgb, var(--dsw-alias-state-success-primary) 12%, transparent), color-mix(in srgb, var(--dsw-alias-state-success-primary) 5%, transparent)); }
.gw-progress-sub[data-state="done"] .gw-progress-sub-dot { background: var(--dsw-alias-state-success-primary); }
.gw-progress-sub[data-state="done"] .gw-progress-sub-word { color: var(--dsw-alias-state-success-primary); }
.gw-progress-sub[data-state="doing"] { border-color: var(--dsw-alias-state-business-primary); background-color: transparent; background-image: linear-gradient(180deg, color-mix(in srgb, var(--dsw-alias-state-business-primary) 12%, transparent), color-mix(in srgb, var(--dsw-alias-state-business-primary) 5%, transparent)); }
.gw-progress-sub[data-state="doing"] .gw-progress-sub-dot { background: var(--dsw-alias-state-business-primary); animation: gw-progress-breathe 1.7s ease-in-out infinite; }
.gw-progress-sub[data-state="doing"] .gw-progress-sub-word { color: var(--dsw-alias-state-business-primary); }
.gw-progress-sub[data-state="pending"] { border-style: dashed; background-color: transparent; background-image: none; }
.gw-progress-sub[data-state="pending"] .gw-progress-sub-dot { background: transparent; box-shadow: inset 0 0 0 1px var(--dsw-alias-state-idle-primary); }
.gw-progress-sub[data-state="pending"] .gw-progress-sub-word { color: var(--dsw-alias-label-secondary, inherit); }
.gw-progress-sub[data-state="failed"], .gw-progress-sub[data-state="blocked"], .gw-progress-sub[data-state="cancelled"] { border-color: color-mix(in srgb, var(--dsw-alias-state-warn-primary) 50%, transparent); background-color: transparent; background-image: linear-gradient(180deg, color-mix(in srgb, var(--dsw-alias-state-warn-primary) 12%, transparent), color-mix(in srgb, var(--dsw-alias-state-warn-primary) 5%, transparent)); }
.gw-progress-sub[data-state="failed"] .gw-progress-sub-dot { background: var(--dsw-alias-state-warn-primary); }
.gw-progress-sub[data-state="failed"] .gw-progress-sub-word { color: var(--dsw-alias-state-warn-primary); }
.gw-progress-sub[data-state="blocked"] .gw-progress-sub-dot { background: var(--dsw-alias-state-warn-primary); }
.gw-progress-sub[data-state="blocked"] .gw-progress-sub-word { color: var(--dsw-alias-state-warn-primary); }
.gw-progress-sub[data-state="cancelled"] .gw-progress-sub-dot { background: var(--dsw-alias-state-warn-primary); }
.gw-progress-sub[data-state="cancelled"] .gw-progress-sub-word { color: var(--dsw-alias-state-warn-primary); }
.gw-progress-node-calls .gw-progress-log-row, .gw-progress-sub-calls .gw-progress-log-row { grid-template-columns: 46px minmax(0, 1fr) auto auto; padding: 6px 4px; }
.gw-progress-node-rejected { margin: 0; padding: 6px 4px; font-size: 12px; color: var(--dsw-alias-label-secondary, inherit); overflow-wrap: anywhere; }
.gw-progress-node-rejected[data-gw-progress-node-rejected="drafts"] { font-weight: 600; color: var(--dsw-alias-state-warn-primary); }
.gw-progress-node-calls [data-gw-progress-task-chain], .gw-progress-sub-calls [data-gw-progress-task-chain] { flex: none; padding: 1px 6px; border: 1px solid var(--dsw-alias-border-l2, currentColor); border-radius: 999px; color: var(--dsw-alias-label-secondary, inherit); font-size: 11px; white-space: nowrap; }
.gw-progress-log-row { display: grid; grid-template-columns: 46px minmax(0, 1fr) auto; gap: 8px; align-items: baseline; padding: 8px 6px; border-bottom: 1px solid var(--dsw-alias-border-l2, currentColor); }
.gw-progress-log-row:last-child { border-bottom: 0; }
.gw-progress-log-time { font-size: 11px; color: var(--dsw-alias-label-secondary, inherit); font-variant-numeric: tabular-nums; }
.gw-progress-log-line { display: flex; align-items: baseline; gap: 6px; min-width: 0; }
.gw-progress-log-role { flex: none; font-size: 13px; font-weight: 600; }
.gw-progress-log-name { min-width: 0; font-size: 13px; color: var(--dsw-alias-label-secondary, inherit); overflow-wrap: anywhere; }
.gw-progress-log-word { flex: none; font-size: 12px; color: var(--dsw-alias-label-secondary, inherit); white-space: nowrap; }
.gw-progress-log-row[data-state="done"] .gw-progress-log-word { color: var(--dsw-alias-state-success-primary); }
.gw-progress-log-row[data-state="doing"] { border-radius: 8px; background: color-mix(in srgb, var(--dsw-alias-state-business-primary) 8%, transparent); }
.gw-progress-log-row[data-state="doing"] .gw-progress-log-word { color: var(--dsw-alias-state-business-primary); font-weight: 600; }
.gw-progress-log-row[data-state="failed"] { border-radius: 8px; background: color-mix(in srgb, var(--dsw-alias-state-warn-primary) 10%, transparent); }
.gw-progress-log-row[data-state="blocked"] { border-radius: 8px; background: color-mix(in srgb, var(--dsw-alias-state-warn-primary) 10%, transparent); }
.gw-progress-log-row[data-state="failed"] .gw-progress-log-word { color: var(--dsw-alias-state-warn-primary); font-weight: 600; }
.gw-progress-log-row[data-state="blocked"] .gw-progress-log-word { color: var(--dsw-alias-state-warn-primary); font-weight: 600; }
.gw-progress-open { display: inline-flex; align-items: center; height: 22px; margin-left: auto; padding: 0 9px; border: 1px solid var(--dsw-alias-border-l2, currentColor); border-radius: 999px; background: transparent; color: inherit; font: inherit; font-size: 11px; white-space: nowrap; }
.gw-progress-open[type="button"] { cursor: pointer; }
.gw-progress-open[type="button"]:hover { border-color: var(--dsw-alias-state-business-primary); }
.gw-progress-foot { display: flex; flex-direction: column; gap: 8px; margin-top: 18px; padding: 0 4px 4px; border-top: 1px solid var(--dsw-alias-border-l2, currentColor); }
.gw-progress-left { margin: 0; padding-top: 10px; font-size: 12px; color: var(--dsw-alias-label-secondary, inherit); font-variant-numeric: tabular-nums; }
.gw-progress-dock { display: flex; flex-direction: column; align-items: stretch; gap: 8px; }
.gw-progress-dock-fill { display: block; width: 100%; height: 40px; border: 0; border-radius: 12px; background: var(--dsw-alias-state-business-primary); color: var(--dsw-alias-label-inverse, inherit); font: inherit; font-size: 14px; font-weight: 600; cursor: pointer; }
.gw-progress-dock-fill:hover { background: color-mix(in srgb, var(--dsw-alias-state-business-primary) 85%, var(--dsw-alias-label-primary, currentColor)); }
.gw-progress-dock-fill:focus-visible { outline: 2px solid var(--dsw-alias-state-business-primary); outline-offset: 3px; }
.gw-progress-filled { margin: 0; text-align: center; font-size: 12px; color: var(--dsw-alias-state-success-primary); }
.gw-progress-empty { padding: 14px 4px; color: var(--dsw-alias-label-secondary, inherit); }
.gw-progress-guardian { box-sizing: border-box; min-width: 0; margin-top: 16px; padding: 11px 14px; border: 1px solid color-mix(in srgb, var(--dsw-alias-state-success-primary) 28%, var(--dsw-alias-border-l2, currentColor)); border-radius: 14px; background: color-mix(in srgb, var(--dsw-alias-state-success-primary) 5%, transparent); }
.gw-progress-guardian[data-state="active"] { border-color: color-mix(in srgb, var(--dsw-alias-state-business-primary) 40%, var(--dsw-alias-border-l2, currentColor)); background: color-mix(in srgb, var(--dsw-alias-state-business-primary) 6%, transparent); }
.gw-progress-guardian[data-state="cancelled"] { border-color: color-mix(in srgb, var(--dsw-alias-state-warn-primary) 38%, var(--dsw-alias-border-l2, currentColor)); background: color-mix(in srgb, var(--dsw-alias-state-warn-primary) 5%, transparent); }
.gw-progress-guardian-blocks { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 6px; }
.gw-progress-guardian-block { display: flex; flex-direction: column; gap: 2px; min-width: 0; padding: 6px 8px; border: 1px solid var(--dsw-alias-border-l2, currentColor); border-radius: 10px; background: color-mix(in srgb, var(--dsw-alias-state-idle-primary) 6%, transparent); }
.gw-progress-guardian-block[data-gw-progress-guardian-block="findings"] { grid-column: 1 / -1; padding: 0; border-color: transparent; background: transparent; }
.gw-progress-guardian-block-label { font-size: 10px; font-weight: 600; letter-spacing: .06em; color: var(--dsw-alias-label-secondary, inherit); overflow-wrap: anywhere; }
.gw-progress-guardian-block-value { font-size: 12px; font-weight: 650; color: var(--dsw-alias-label-primary, inherit); overflow-wrap: anywhere; }
.gw-progress-guardian[data-state="active"] [data-gw-progress-guardian-block="status"] .gw-progress-guardian-block-value { color: var(--dsw-alias-state-business-primary); }
.gw-progress-guardian[data-state="finished"] [data-gw-progress-guardian-block="status"] .gw-progress-guardian-block-value { color: var(--dsw-alias-state-success-primary); }
.gw-progress-guardian[data-state="cancelled"] [data-gw-progress-guardian-block="status"] .gw-progress-guardian-block-value { color: var(--dsw-alias-state-warn-primary); }
.gw-progress-guardian-empty { margin: 0; color: var(--dsw-alias-label-secondary, inherit); font-size: 11px; }
.gw-progress-guardian-list { display: grid; gap: 6px; margin: 0; padding: 0; list-style: none; }
.gw-progress-guardian-list li { display: flex; align-items: center; flex-wrap: wrap; gap: 4px 8px; min-width: 0; padding: 6px 8px; border-inline-start: 3px solid var(--dsw-alias-state-warn-primary, currentColor); border-radius: 7px; background: color-mix(in srgb, var(--dsw-alias-state-warn-primary) 5%, transparent); font-size: 11px; }
.gw-progress-guardian-list li[data-action="rescue"] { border-inline-start-color: var(--dsw-alias-state-success-primary, currentColor); background: color-mix(in srgb, var(--dsw-alias-state-success-primary) 5%, transparent); }
.gw-progress-guardian-finding-label { font-weight: 600; }
.gw-progress-guardian-finding-action { color: var(--dsw-alias-label-secondary, inherit); }
@keyframes gw-progress-breathe { 0%, 100% { opacity: 1; } 50% { opacity: 0.45; } }
@keyframes gw-progress-pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.45; } }
@media (prefers-reduced-motion: reduce) {
  .gw-progress-node[data-state="doing"] .gw-progress-node-dot, .gw-progress-chip[data-state="running"] .gw-progress-chip-dot, .gw-progress-sub[data-state="doing"] .gw-progress-sub-dot { animation: none; }
}
@media (max-width: 720px) {
  .gw-progress-cols { gap: 8px; }
  .gw-progress-col { flex: 1 1 calc(50% - 4px); max-width: calc(50% - 4px); }
}
@media (max-width: 480px) {
  .gw-progress-col { flex: 1 1 100%; max-width: 100%; }
  .gw-progress-dock { flex-direction: column; align-items: stretch; }
  .gw-progress-node-calls .gw-progress-log-row { grid-template-columns: minmax(0, 1fr) auto; }
  .gw-progress-sub-calls .gw-progress-log-row { grid-template-columns: minmax(0, 1fr) auto; }
  .gw-progress-node-calls .gw-progress-log-time { display: none; }
  .gw-progress-sub-calls .gw-progress-log-time { display: none; }
}
